import Model from 'flarum/common/Model';
export default class Advertiser extends Model {
  name = (() => Model.attribute('name'))();
  contactEmail = (() => Model.attribute('contactEmail'))();
  notes = (() => Model.attribute('notes'))();

  /**
   * Whether a report link exists, never the token itself. The token is the one
   * credential here that reaches somebody outside the forum, so it leaves the
   * server exactly once: in the response to the request that created it.
   */
  hasReportToken = (() => Model.attribute('hasReportToken'))();
  reportTokenExpiresAt = (() => Model.attribute('reportTokenExpiresAt', Model.transformDate))();
  campaigns = (() => Model.hasMany('campaigns'))();
}
flarum.reg.add('datlechin-placement', 'admin/models/Advertiser', Advertiser);