import Model from 'flarum/common/Model';

/**
 * An administrator's overrides for one slot.
 *
 * The id is the placement key, and there is no create endpoint: a slot exists
 * because a component renders it, and the row is written the first time
 * somebody changes something about it.
 */
export default class PlacementSetting extends Model {
  enabled = (() => Model.attribute('enabled'))();
  maxFill = (() => Model.attribute('maxFill'))();
  fallback = (() => Model.attribute('fallback'))();
  labelMode = (() => Model.attribute('labelMode'))();

  /** random | sticky. Sticky holds the slot's choice for the rest of the visit. */
  rotation = (() => Model.attribute('rotation'))();
  reservePhone = (() => Model.attribute('reservePhone'))();
  reserveTablet = (() => Model.attribute('reserveTablet'))();
  reserveDesktop = (() => Model.attribute('reserveDesktop'))();
  everyN = (() => Model.attribute('everyN'))();
  repeatLimit = (() => Model.attribute('repeatLimit'))();
  sortOrder = (() => Model.attribute('sortOrder'))();
}
flarum.reg.add('datlechin-placement', 'admin/models/PlacementSetting', PlacementSetting);